function source(title, organisationOrAuthor, urlOrReference, sourceType, relevantClaim) {
  return Object.freeze({ title, organisationOrAuthor, urlOrReference, publicationDate: null, accessDate: ACCESS_DATE, sourceType, reviewStatus: "approved", relevantClaim });
}

function q(stableSuffix, sourceKey, countryScope, subregionScope, communityScope, category, questionText, correct, distractors, explanation, sensitivityNotes = null) {
  return Object.freeze({ stableSuffix, sourceKey, countryScope, subregionScope, communityScope, category, questionText, correct, distractors, explanation, sensitivityNotes });
}

function rotate(values, amount) {
  return [...values.slice(amount), ...values.slice(0, amount)];
}

function makeQuestion(spec, index) {
  const optionTexts = rotate([spec.correct, ...spec.distractors], index % 4);
  const answerOptions = optionTexts.map((text, optionIndex) => ({ id: `o${optionIndex + 1}`, text }));
  const acceptedId = answerOptions.find((option) => option.text === spec.correct).id;
  const difficulty = ["introductory", "intermediate", "introductory", "intermediate", "advanced"][index % 5];
  return {
    stableId: `east_${spec.stableSuffix}`,
    version: 1,
    region: "east",
    countryScope: spec.countryScope,
    subregionScope: spec.subregionScope,
    communityScope: spec.communityScope,
    category: spec.category,
    difficulty,
    questionKind: "single",
    questionText: spec.questionText,
    answerOptions,
    acceptedAnswers: [[acceptedId]],
    explanation: spec.explanation,
    sources: [sources[spec.sourceKey]],
    reviewer: spec.sensitivityNotes ? RESEARCH_REVIEWER : null,
    reviewDate: spec.sensitivityNotes ? ACCESS_DATE : null,
    sensitivityNotes: spec.sensitivityNotes,
    language: "en",
    locale: "en",
    lifecycleStatus: "draft",
    publishedAt: null,
    retiredAt: null,
    validFrom: null,
    validUntil: null,
    scoringWeight: 1,
    imageProvenance: [],
    audioProvenance: [],
  };
}

function csvCell(value) {
  const safe = neutralizeCsvFormula(String(value ?? ""));
  return /[",\r\n]/.test(safe) ? `"${safe.replaceAll('"', '""')}"` : safe;
}

function csv(rows) {
  return `${rows.map((row) => row.map(csvCell).join(",")).join("\n")}\n`;
}

function tally(values) {
  return [...values.reduce((map, value) => map.set(value, (map.get(value) || 0) + 1), new Map()).entries()].sort(([a], [b]) => a.localeCompare(b));
}

function table(rows) {
  return rows.map(([name, count]) => `| ${name} | ${count} |`).join("\n");
}

const document = validateQuestionBankDocument({ schemaVersion: "question-bank-v1", questions: specs.map(makeQuestion) });
if (document.questions.length < 65) throw new Error(`expected_at_least_65_candidates_got_${document.questions.length}`);
const legacy = await buildLegacyQuestionBankDocument();
const west = validateQuestionBankDocument(JSON.parse(await readFile(westDraftFile, "utf8")));
const comparisonCatalogue = validateQuestionBankDocument({ schemaVersion: "question-bank-v1", questions: [...legacy.questions, ...west.questions] });
const duplicateReport = previewQuestionBankImport(document, comparisonCatalogue);
const sourceEntries = Object.entries(sources);
const sourceCounts = new Map(sourceEntries.map(([key]) => [key, specs.filter((spec) => spec.sourceKey === key).length]));
const difficultyCounts = tally(document.questions.map((question) => question.difficulty));
const categoryCounts = tally(document.questions.map((question) => question.category));
const countryOccurrences = tally(document.questions.flatMap((question) => question.countryScope.split("; ")));
const scopeCounts = tally(document.questions.map((question) => question.countryScope.includes(";") ? "multi-country" : question.communityScope ? "country-and-community" : "country-only"));
const sensitiveQuestions = document.questions.filter((question) => question.sensitivityNotes);

const reviewRows = [["stableId", "version", "countryScope", "subregionScope", "communityScope", "category", "difficulty", "questionText", "acceptedAnswer", "lifecycleStatus", "specialistReviewRequired", "sensitivityNotes", "sourceTitle", "sourceUrl", "humanDecision", "humanReviewer", "humanReviewDate", "humanReviewNotes"]];
for (const question of document.questions) {
  const accepted = question.acceptedAnswers[0].map((id) => question.answerOptions.find((option) => option.id === id).text).join(" | ");
  reviewRows.push([question.stableId, question.version, question.countryScope, question.subregionScope, question.communityScope, question.category, question.difficulty, question.questionText, accepted, question.lifecycleStatus, question.sensitivityNotes ? "yes" : "no", question.sensitivityNotes, question.sources[0].title, question.sources[0].urlOrReference, "pending", "", "", ""]);
}

const sourceRows = [["sourceId", "title", "organisationOrAuthor", "urlOrReference", "sourceType", "accessDate", "candidateCount", "relevantClaim"]];
sourceEntries.forEach(([key, item], index) => sourceRows.push([`EA-S${String(index + 1).padStart(2, "0")}`, item.title, item.organisationOrAuthor, item.urlOrReference, item.sourceType, item.accessDate, sourceCounts.get(key), item.relevantClaim]));

const coverage = `# East Africa draft question-bank coverage\n\nGenerated ${ACCESS_DATE}. These are research candidates, not culturally approved or publishable questions. The collection uses the application's broad Eastern Africa edition scope; each record preserves its exact country and community scope rather than treating the region as culturally uniform.\n\n## Totals\n\n- Candidates: ${document.questions.length}\n- Lifecycle: draft (${document.questions.length})\n- Unique authoritative sources: ${sourceEntries.length}\n- Candidates flagged for specialist review: ${sensitiveQuestions.length}\n- Media assets: 0\n\n## Difficulty\n\n| Difficulty | Count |\n| --- | ---: |\n${table(difficultyCounts)}\n\n## Category\n\n| Category | Count |\n| --- | ---: |\n${table(categoryCounts)}\n\n## Country occurrence\n\nMulti-country questions count once for each named country.\n\n| Country | Candidate occurrences |\n| --- | ---: |\n${table(countryOccurrences)}\n\n## Scope\n\n| Scope type | Count |\n| --- | ---: |\n${table(scopeCounts)}\n\n## Communities and local scopes represented\n\n${[...new Set(document.questions.map((question) => question.communityScope).filter(Boolean))].sort().map((scope) => `- ${scope}`).join("\n")}\n`;

const underrepresented = `# East Africa under-representation report\n\nCandidate occurrence counts are a research-coverage measure, not population weights or cultural rankings. Country names follow each source's documented practice; cross-border entries count once for each named country.\n\n## Lowest represented countries in the current pack\n\n${countryOccurrences.filter(([, count]) => count < 4).map(([country, count]) => `- **${country}: ${count}.** Locally authored institutional sources and community reviewers are needed before a later approval target is set.`).join("\n")}\n\n## Countries and communities not yet represented\n\n- Comoros and South Sudan need reliable, publicly accessible cultural sources with sufficiently precise community scope. No question was invented to fill those gaps.\n- Additional Eritrean, Djiboutian, Somali, Mauritian and Seychellois everyday-life material should come from local institutions and community reviewers.\n\n## Known collection gaps\n\n- Everyday greetings outside the carefully sourced Kiswahili examples need language-specific sources and fluent community review.\n- Well-supported local proverbs remain limited because translation, attribution and context require language specialists.\n- Contemporary urban life, popular arts and hospitality outside formal heritage programmes need more locally authored evidence.\n- Wedding coverage is limited to one well-documented Mauritian practice and references inside other performance records; none is generalized across the region.\n- Sacred, initiatory, healing and oral-law records need knowledge-holder review before any wording can progress.\n`;

const issueLog = `# East Africa cultural-review issue log\n\nAll ${document.questions.length} candidates remain draft. Source approval in the import contract means that the reference passed research-source screening; it is not cultural approval of the question.\n\n## Specialist review queue (${sensitiveQuestions.length})\n\n${sensitiveQuestions.map((question) => `- **${question.stableId}:** ${question.sensitivityNotes}`).join("\n")}\n\n## Collection-wide review questions\n\n- Confirm country, community and subregion names, diacritics and preferred English renderings with reviewers from the named communities.\n- Confirm that the public wording for sacred, initiatory, healing, religious and customary-law material stays within community disclosure boundaries.\n- Review distractors for unintended ethnic, religious, political, health or gender implications.\n- Review Kiswahili forms with fluent speakers from multiple East African settings; do not imply uniform usage.\n- Review oral-history questions as community memory rather than independently proven chronology.\n- Review colonial and enslavement history with trauma-informed Eritrean, Seychellois and relevant local historians.\n- Recheck every URL and factual claim on the human-review date.\n`;

const duplicateAnalysis = `# East Africa duplicate and near-duplicate analysis\n\nCompared ${document.questions.length} draft candidates against each other, the verified 60-question transitional catalogue and all ${west.questions.length} West Africa drafts using the Prompt 20 import preview.\n\n- Exact duplicate question texts: ${duplicateReport.exactDuplicates.length}\n- Token near-duplicate pairs at the engine threshold: ${duplicateReport.nearDuplicates.length}\n- Writes performed: ${duplicateReport.writesPerformed}\n\n## Exact duplicates\n\n${duplicateReport.exactDuplicates.length ? duplicateReport.exactDuplicates.map((item) => `- ${item}`).join("\n") : "None detected."}\n\n## Near duplicates\n\n${duplicateReport.nearDuplicates.length ? duplicateReport.nearDuplicates.map((item) => `- ${item.left} / ${item.right}: ${item.similarity}`).join("\n") : "None detected at the configured threshold."}\n\nHuman reviewers should still assess conceptual overlap around greetings, food, textiles, performance, heritage buildings and cross-border traditions even where wording falls below the automated threshold.\n`;

await mkdir(outputDir, { recursive: true });
await Promise.all([
  writeFile(resolve(outputDir, "east-africa-draft-v1.json"), `${JSON.stringify(document, null, 2)}\n`, "utf8"),
  writeFile(resolve(outputDir, "east-africa-cultural-review.csv"), csv(reviewRows), "utf8"),
  writeFile(resolve(outputDir, "east-africa-source-register.csv"), csv(sourceRows), "utf8"),
  writeFile(resolve(outputDir, "east-africa-review-issues.md"), issueLog, "utf8"),
  writeFile(resolve(outputDir, "east-africa-coverage.md"), coverage, "utf8"),
  writeFile(resolve(outputDir, "east-africa-underrepresented.md"), underrepresented, "utf8"),
  writeFile(resolve(outputDir, "east-africa-duplicate-analysis.md"), duplicateAnalysis, "utf8"),
]);

console.log(JSON.stringify({ candidates: document.questions.length, sources: sourceEntries.length, specialistReview: sensitiveQuestions.length, difficulty: Object.fromEntries(difficultyCounts), exactDuplicates: duplicateReport.exactDuplicates.length, nearDuplicates: duplicateReport.nearDuplicates.length }, null, 2));
